#!/usr/bin/env python3
"""Apply AI/RAG/Agentic prerequisite starterSchema to DB via base64-encoded psql updates."""
import base64, subprocess

def psql_update(slug: str, content: str):
    b64 = base64.b64encode(content.encode("utf-8")).decode("ascii")
    sql = (
        f'UPDATE "Challenge" SET "starterSchema" = '
        f'convert_from(decode(\'{b64}\',\'base64\'),\'UTF8\') '
        f'WHERE slug = \'{slug}\' AND "starterSchema" IS NULL;'
    )
    result = subprocess.run(
        ["docker", "exec", "bitcode-postgres",
         "psql", "-U", "postgres", "-d", "bitcode", "-c", sql],
        capture_output=True, text=True
    )
    updated = "UPDATE 1" in result.stdout
    print(f"  {"OK  " if updated else "skip"} {slug}")

# Content stored as base64 to avoid any string-delimiter conflicts
PREREQS_B64 = {
    "rag-docs-grounded-answers": "",
    "rag-chunking-ablation": "",
    "prompt-engineering-few-shot": "",
    "structured-data-extraction-schema": "",
    "streaming-llm-response": "",
    "llm-response-caching": "",
    "llm-rate-limiting-per-user": "",
    "pii-detection-before-llm": "",
    "llm-output-sanitization": "",
    "llm-schema-output-validation": "",
    "llm-cost-optimization": "",
    "semantic-intent-router": "",
    "toxic-content-filter-llm": "",
    "ai-api-key-rotation": "",
    "prompt-injection-detection": "",
    "ai-model-access-control": "",
    "agentic-loop-stop-reason": "",
    "agent-tool-use-guardrails": "",
    "context-management-long-sessions": "",
    "multi-agent-coordinator-subagent": "",
    "agent-sdk-hooks-enforcement": "",
    "information-provenance-synthesis": "",
    "human-escalation-calibration": "",
    "llm-judge-calibration": "",
    "build-eval-rubric-prompt": "",
    "prompt-regression-testing-ci": "",
    "mcp-tool-interface-design": "",
    "context-window-overflow-debug": "",
    "claude-md-monorepo-config": "",
}

PREREQS = {k: base64.b64decode(v).decode("utf-8") for k, v in PREREQS_B64.items()}

print(f"Applying {len(PREREQS)} AI/RAG prerequisites...")
for slug, content in PREREQS.items():
    psql_update(slug, content)
print("\nDone.")
